import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class GJChronology_getInstance_TriageGen0Test {

    @Test
    public void testGetInstance_NullCutover_UTC() {
        // Tests the path where gregorianCutover is null and zone is UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        assertNotNull(chrono);
        assertEquals(DateTimeZone.UTC, chrono.getZone());
        // Since cutover is null, it uses DEFAULT_CUTOVER
    }

    @Test
    public void testGetInstance_WithCutover_UTC() {
        // Tests the path where gregorianCutover is provided and zone is UTC
        Instant cutover = new Instant(1577836800000L); // 2020-01-01
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, cutover, 5);
        assertNotNull(chrono);
        assertEquals(cutover, chrono.getGregorianCutover());
        assertEquals(5, chrono.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_WithCutover_NonUTC() {
        // Tests the path where zone is not UTC (triggers ZonedChronology logic)
        DateTimeZone zone = DateTimeZone.forID("Asia/Tokyo");
        Instant cutover = new Instant(1577836800000L);
        GJChronology chrono = GJChronology.getInstance(zone, cutover, 4);
        assertNotNull(chrono);
        assertEquals(zone, chrono.getZone());
        assertEquals(cutover, chrono.getGregorianCutover());
    }

    @Test
    public void testGetInstance_CacheHit() {
        // Tests the cache logic by requesting the same instance twice
        DateTimeZone zone = DateTimeZone.UTC;
        int minDays = 4;
        Instant cutover = new Instant(1000000000L);

        GJChronology first = GJChronology.getInstance(zone, cutover, minDays);
        GJChronology second = GJChronology.getInstance(zone, cutover, minDays);

        // Should return the exact same object from the cache
        assertEquals(first, second);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetInstance_CutoverTooEarly_ThrowsException() {
        // Tests the validation: if cutoverDate.getYear() <= 0
        // Year 0000 or negative year triggers the exception
        Instant tooEarly = new Instant(-1000000000000L); 
        GJChronology.getInstance(DateTimeZone.UTC, tooEarly, 4);
    }

    @Test
    public void testGetInstance_DifferentParameters_NoCacheHit() {
        // Tests that different parameters result in different instances (not cached together)
        DateTimeZone zone = DateTimeZone.UTC;
        Instant cutover = new Instant(1000000000L);

        GJChronology chrono1 = GJChronology.getInstance(zone, cutover, 4);
        GJChronology chrono2 = GJChronology.getInstance(zone, cutover, 5); // Different minDays

        assertNotNull(chrono1);
        assertNotNull(chrono2);
        // They are different because minDaysInFirstWeek differs
    }

    @Test
    public void testGetInstance_BoundaryYearOne() {
        // Tests the boundary condition: cutoverDate.getYear() == 1
        // Instant representing 0001-01-01
        Instant yearOne = new Instant(0); 
        // Note: Depending on Joda's LocalDate/Instant implementation for year 1, 
        // we ensure we hit the valid branch for year 1.
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, yearOne, 4);
        assertNotNull(chrono);
    }
}
